  const getGarmentPatches = (category, id, variant, size = 'M', bodyType = 'Medium') => {
    const patches = [];
    const meta = _configGarments.GARMENT_META[category];
    if (!meta) return patches;
    const variantMeta = meta.variants[variant];
    const occludes = variantMeta?.occludes || [];
    const sizeMap = CLOTHING_ASSET_MAP[category]?.[id]?.[variant]?.[size] || CLOTHING_ASSET_MAP[category]?.[id]?.[variant]?.['M'];
    if (!sizeMap) return patches;
    for (const [part, data] of Object.entries(sizeMap)) {
      if (part === 'transform') continue; // In case any old top-level transform remains

      // data can be an object with {source, transform} (new format) or just the source (old format)
      const source = data?.source || data;
      const patchTransform = data?.transform || {
        x: 0,
        y: 0,
        scale: 1
      };
      let z = meta.layer; // BASE: TROUSER=100, TSHIRT=110, SHIRT=200

      // Fine tune Z
      if (category === 'shirt') {
        if (part === 'sleeve') z = 215; // SHIRT_SLEEVE
        if (part === 'back') z = 0; // Behind body
        // If buttoned_tucked, we tuck the tummy
        if (part === 'tummy' && variant === 'buttoned_tucked') z = 95; // Under trouser (100)
      }
      if (category === 'trouser') {
        if (part === 'tummy') z = 105; // Waistband over base trouser
      }
      patches.push({
        id: `${category}_${id}_${part}`,
        category,
        part,
        source,
        z,
        occludes,
        xOffset: patchTransform.x,
        yOffset: patchTransform.y,
        scale: patchTransform.scale,
        scaleX: patchTransform.scaleX,
        maskBottom: data?.maskBottom
      });
    }
    return patches;
  };

